-- ═══════════════════════════════════════════════════════════════════════
--  DirectorioCerca — Esquema de base de datos (PostgreSQL 12+)
--  Ejecutar con:  psql -U postgres -d directoriocerca -f database.sql
--  o automáticamente con:  npm run db:init
-- ═══════════════════════════════════════════════════════════════════════

-- ── Extensiones ─────────────────────────────────────────────────────────
-- pg_trgm: búsquedas difusas y por similitud (LIKE/ILIKE rápidos con índices).
-- unaccent: búsqueda sin acentos.
CREATE EXTENSION IF NOT EXISTS pg_trgm;
CREATE EXTENSION IF NOT EXISTS unaccent;

-- ── Función para mantener "updated_at" ──────────────────────────────────
CREATE OR REPLACE FUNCTION set_updated_at()
RETURNS TRIGGER AS $$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- ═══════════════════════════════════════════════════════════════════════
--  TABLAS
-- ═══════════════════════════════════════════════════════════════════════

-- ── CATEGORÍAS ──────────────────────────────────────────────────────────
DROP TABLE IF EXISTS cambios_log CASCADE;
DROP TABLE IF EXISTS suscripciones CASCADE;
DROP TABLE IF EXISTS mensajes CASCADE;
DROP TABLE IF EXISTS fotos CASCADE;
DROP TABLE IF EXISTS anuncios CASCADE;
DROP TABLE IF EXISTS categorias CASCADE;
DROP TABLE IF EXISTS administrador CASCADE;
DROP TABLE IF EXISTS ciudades CASCADE;
DROP TABLE IF EXISTS departamentos CASCADE;

CREATE TABLE categorias (
  id          BIGSERIAL PRIMARY KEY,
  nombre      VARCHAR(120) NOT NULL UNIQUE,
  slug        VARCHAR(140) NOT NULL UNIQUE,
  icono       VARCHAR(60),
  orden       SMALLINT NOT NULL DEFAULT 0,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- ── DEPARTAMENTOS Y CIUDADES DE COLOMBIA (DANE – DIVIPOLA) ───────────────
CREATE TABLE departamentos (
  id          BIGSERIAL PRIMARY KEY,
  codigo      VARCHAR(3) NOT NULL UNIQUE,           -- código DIVIPOLA del departamento
  nombre      VARCHAR(120) NOT NULL UNIQUE,
  slug        VARCHAR(140) NOT NULL UNIQUE,
  capital     VARCHAR(120) NOT NULL,                -- ciudad capital (Cundinamarca → Bogotá D.C.)
  created_at  TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE ciudades (
  id              BIGSERIAL PRIMARY KEY,
  departamento_id BIGINT NOT NULL REFERENCES departamentos(id) ON DELETE CASCADE,
  codigo          VARCHAR(8) NOT NULL UNIQUE,       -- código DIVIPOLA del municipio
  nombre          VARCHAR(120) NOT NULL,
  es_capital      BOOLEAN NOT NULL DEFAULT FALSE,
  tipo            VARCHAR(30) NOT NULL DEFAULT 'Municipio',  -- Municipio / Isla / Área no municipalizada
  latitud         NUMERIC(10,7),
  longitud        NUMERIC(10,7),
  created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE (departamento_id, nombre)
);

-- ── ADMINISTRADOR (único usuario del sistema) ──────────────────────────
CREATE TABLE administrador (
  id             BIGSERIAL PRIMARY KEY,
  nombre         VARCHAR(120) NOT NULL,
  email          VARCHAR(190) NOT NULL UNIQUE,
  password_hash  VARCHAR(255) NOT NULL,          -- bcrypt
  ultimo_login   TIMESTAMPTZ,
  created_at     TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- ── ANUNCIOS ────────────────────────────────────────────────────────────
CREATE TABLE anuncios (
  id                    BIGSERIAL PRIMARY KEY,
  razon_social          VARCHAR(200) NOT NULL,
  slug                  VARCHAR(220) NOT NULL UNIQUE,        -- URL amigable
  descripcion_50        VARCHAR(700) NOT NULL,               -- portafolio (~50 palabras)
  direccion             VARCHAR(300),
  telefono_fijo         VARCHAR(40),
  telefono_movil        VARCHAR(40),
  email                 VARCHAR(190),
  sitio_web             VARCHAR(300),
  youtube               VARCHAR(300),
  facebook              VARCHAR(300),
  instagram             VARCHAR(300),
  tiktok                VARCHAR(300),
  otras_redes           JSONB,
  categoria_id          BIGINT REFERENCES categorias(id) ON DELETE SET NULL,
  ciudad                VARCHAR(120),
  pais                  VARCHAR(120),
  latitud               NUMERIC(10,7),
  longitud              NUMERIC(10,7),
  palabras_clave        VARCHAR(600),                        -- 10 keywords separadas por comas
  estado                VARCHAR(20) NOT NULL DEFAULT 'activo'
                          CHECK (estado IN ('activo','vencido','deshabilitado','pendiente')),
  fecha_inicio          DATE NOT NULL DEFAULT CURRENT_DATE,
  fecha_vencimiento     DATE NOT NULL,
  aviso_30_enviado      BOOLEAN NOT NULL DEFAULT FALSE,
  cambios_usados        SMALLINT NOT NULL DEFAULT 0,         -- máx. 6
  -- Columna de búsqueda full-text ponderada (razón social > keywords > descripción)
  search_vector         tsvector GENERATED ALWAYS AS (
                          setweight(to_tsvector('spanish', COALESCE(razon_social, '')), 'A') ||
                          setweight(to_tsvector('spanish', COALESCE(palabras_clave, '')), 'B') ||
                          setweight(to_tsvector('spanish', COALESCE(descripcion_50, '')), 'C')
                        ) STORED,
  created_at            TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at            TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- ── FOTOS (hasta 11 por anuncio) ────────────────────────────────────────
CREATE TABLE fotos (
  id          BIGSERIAL PRIMARY KEY,
  anuncio_id  BIGINT NOT NULL REFERENCES anuncios(id) ON DELETE CASCADE,
  url         VARCHAR(500) NOT NULL,
  public_id   VARCHAR(255),                -- identificador en CDN (Cloudinary/S3)
  orden       SMALLINT NOT NULL DEFAULT 0,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- ── MENSAJES (formulario de contacto 24/7) ──────────────────────────────
CREATE TABLE mensajes (
  id          BIGSERIAL PRIMARY KEY,
  anuncio_id  BIGINT REFERENCES anuncios(id) ON DELETE SET NULL,
  nombre      VARCHAR(120) NOT NULL,
  email       VARCHAR(190) NOT NULL,
  telefono    VARCHAR(40),
  mensaje     TEXT NOT NULL,
  ip          VARCHAR(45),
  leido       BOOLEAN NOT NULL DEFAULT FALSE,
  fecha       TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- ── SUSCRIPCIONES (periodos de 12 meses) ────────────────────────────────
CREATE TABLE suscripciones (
  id           BIGSERIAL PRIMARY KEY,
  anuncio_id   BIGINT NOT NULL REFERENCES anuncios(id) ON DELETE CASCADE,
  fecha_inicio DATE NOT NULL,
  fecha_fin    DATE NOT NULL,
  estado       VARCHAR(20) NOT NULL DEFAULT 'activa'
                 CHECK (estado IN ('activa','vencida','cancelada')),
  created_at   TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- ── CAMBIOS_LOG (auditoría de los 6 cambios por anuncio) ────────────────
CREATE TABLE cambios_log (
  id          BIGSERIAL PRIMARY KEY,
  anuncio_id  BIGINT NOT NULL REFERENCES anuncios(id) ON DELETE CASCADE,
  admin_id    BIGINT REFERENCES administrador(id) ON DELETE SET NULL,
  detalle     VARCHAR(300) NOT NULL,
  fecha       TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- ═══════════════════════════════════════════════════════════════════════
--  ÍNDICES (rendimiento a escala de miles/millones de registros)
-- ═══════════════════════════════════════════════════════════════════════

-- Full-text (GIN sobre tsvector ponderado)
CREATE INDEX idx_an_search_vector   ON anuncios USING GIN (search_vector);
-- Búsqueda difusa por nombre (typos) y por palabras clave
CREATE INDEX idx_an_razon_trgm      ON anuncios USING GIN (razon_social gin_trgm_ops);
CREATE INDEX idx_an_palabras_trgm   ON anuncios USING GIN (palabras_clave gin_trgm_ops);

-- Índices obligatorios del requerimiento
CREATE INDEX idx_an_categoria       ON anuncios (categoria_id);
CREATE INDEX idx_an_ciudad_pais      ON anuncios (ciudad, pais);
CREATE INDEX idx_an_estado           ON anuncios (estado);
CREATE INDEX idx_an_vencimiento      ON anuncios (fecha_vencimiento);
-- Índice compuesto para el listado público más frecuente
CREATE INDEX idx_an_estado_cat       ON anuncios (estado, categoria_id);
CREATE INDEX idx_an_estado_venc      ON anuncios (estado, fecha_vencimiento);

CREATE INDEX idx_fotos_anuncio       ON fotos (anuncio_id, orden);
CREATE INDEX idx_msg_anuncio         ON mensajes (anuncio_id);
CREATE INDEX idx_msg_leido           ON mensajes (leido);
CREATE INDEX idx_sub_anuncio         ON suscripciones (anuncio_id);
CREATE INDEX idx_sub_estado          ON suscripciones (estado);
CREATE INDEX idx_sub_fin             ON suscripciones (fecha_fin);
CREATE INDEX idx_cambios_anuncio     ON cambios_log (anuncio_id);

-- Geografía (catálogo DIVIPOLA)
CREATE INDEX idx_ciudades_depto      ON ciudades (departamento_id);
CREATE INDEX idx_ciudades_nombre     ON ciudades (nombre);

-- ── Trigger updated_at ──────────────────────────────────────────────────
DROP TRIGGER IF EXISTS trg_anuncios_updated ON anuncios;
CREATE TRIGGER trg_anuncios_updated
  BEFORE UPDATE ON anuncios
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

